{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "$id": "https://aisoc.org/schemas/twin/services_manifest_schema.json",
    "title": "AI-SoC Digital Twin Services Topology and Manifest Specification",
    "description": "JSON Schema defining runtime service topologies, IPC channels, process resource budgets, and systemd units (TWIN-02 / ICD-VMWARE-SOC-TWIN-20261029)",
    "type": "object",
    "required": [
        "schema_version",
        "generation_id",
        "manifest_revision",
        "target_environments",
        "services"
    ],
    "additionalProperties": false,
    "properties": {
        "schema_version": {
            "type": "integer",
            "const": 2,
            "description": "Manifest schema version 2"
        },
        "generation_id": {
            "type": "integer",
            "minimum": 1,
            "description": "System topology generation tracker"
        },
        "manifest_revision": {
            "type": "string",
            "pattern": "^[0-9]{8}_rev[0-9]+$",
            "description": "Revision timestamp tag (e.g., 20261029_rev2)"
        },
        "target_environments": {
            "type": "array",
            "items": {
                "type": "string",
                "enum": [
                    "vmware",
                    "soc"
                ]
            },
            "minItems": 1
        },
        "services": {
            "type": "array",
            "minItems": 4,
            "maxItems": 10,
            "description": "Full module service descriptors; first slice requires all 4 operational services",
            "items": {
                "$ref": "#/definitions/ServiceDescriptor"
            },
            "allOf": [
                {
                    "contains": {
                        "type": "object",
                        "properties": {
                            "name": {
                                "const": "forward-service"
                            }
                        },
                        "required": [
                            "name"
                        ]
                    }
                },
                {
                    "contains": {
                        "type": "object",
                        "properties": {
                            "name": {
                                "const": "device-manager"
                            }
                        },
                        "required": [
                            "name"
                        ]
                    }
                },
                {
                    "contains": {
                        "type": "object",
                        "properties": {
                            "name": {
                                "const": "ui-gateway"
                            }
                        },
                        "required": [
                            "name"
                        ]
                    }
                },
                {
                    "contains": {
                        "type": "object",
                        "properties": {
                            "name": {
                                "const": "browser-hmi"
                            }
                        },
                        "required": [
                            "name"
                        ]
                    }
                }
            ]
        }
    },
    "definitions": {
        "ResourceBudget": {
            "type": "object",
            "required": [
                "rss_mb_max",
                "cpu_percent_max"
            ],
            "additionalProperties": false,
            "properties": {
                "rss_mb_max": {
                    "type": "number",
                    "minimum": 1,
                    "maximum": 512,
                    "description": "Maximum resident set size in megabytes"
                },
                "cpu_percent_max": {
                    "type": "number",
                    "minimum": 1,
                    "maximum": 100,
                    "description": "Maximum single-core CPU utilization percentage limit"
                }
            }
        },
        "SystemdSpec": {
            "type": "object",
            "required": [
                "unit_name",
                "restart_policy",
                "restart_sec",
                "sd_notify"
            ],
            "additionalProperties": false,
            "properties": {
                "unit_name": {
                    "type": "string",
                    "pattern": "^[a-z0-9_-]+\\.service$"
                },
                "restart_policy": {
                    "type": "string",
                    "enum": [
                        "always",
                        "on-failure",
                        "no"
                    ]
                },
                "restart_sec": {
                    "type": "number",
                    "minimum": 0
                },
                "sd_notify": {
                    "type": "boolean",
                    "description": "True if process uses sd_notify(READY=1)"
                }
            }
        },
        "DdsIpcChannel": {
            "type": "object",
            "required": [
                "topic",
                "message_type",
                "direction",
                "qos"
            ],
            "additionalProperties": false,
            "properties": {
                "topic": {
                    "type": "string"
                },
                "message_type": {
                    "type": "string"
                },
                "direction": {
                    "type": "string",
                    "enum": [
                        "PUB",
                        "SUB"
                    ]
                },
                "qos": {
                    "type": "object",
                    "required": [
                        "reliability",
                        "durability",
                        "history_depth"
                    ],
                    "additionalProperties": false,
                    "properties": {
                        "reliability": {
                            "type": "string",
                            "enum": [
                                "RELIABLE",
                                "BEST_EFFORT"
                            ]
                        },
                        "durability": {
                            "type": "string",
                            "enum": [
                                "VOLATILE",
                                "TRANSIENT_LOCAL"
                            ]
                        },
                        "history_depth": {
                            "type": "integer",
                            "minimum": 1,
                            "maximum": 100
                        }
                    }
                }
            }
        },
        "DbusIpcChannel": {
            "type": "object",
            "required": [
                "bus_type",
                "object_path",
                "interface_name",
                "role"
            ],
            "additionalProperties": false,
            "properties": {
                "bus_type": {
                    "type": "string",
                    "enum": [
                        "session",
                        "system"
                    ]
                },
                "bus_name": {
                    "type": "string"
                },
                "object_path": {
                    "type": "string"
                },
                "interface_name": {
                    "type": "string"
                },
                "role": {
                    "type": "string",
                    "enum": [
                        "server",
                        "client"
                    ]
                }
            }
        },
        "HttpIpcChannel": {
            "type": "object",
            "required": [
                "port",
                "static_root",
                "endpoints"
            ],
            "additionalProperties": false,
            "properties": {
                "port": {
                    "type": "integer",
                    "minimum": 1024,
                    "maximum": 65535
                },
                "static_root": {
                    "type": "string"
                },
                "endpoints": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                }
            }
        },
        "SerialChannel": {
            "type": "object",
            "required": [
                "device_node",
                "baud_rate",
                "parity",
                "timeout_ms",
                "exclusive_lock"
            ],
            "additionalProperties": false,
            "properties": {
                "device_node": {
                    "type": "string"
                },
                "baud_rate": {
                    "type": "integer",
                    "enum": [
                        9600,
                        115200,
                        921600
                    ]
                },
                "parity": {
                    "type": "string",
                    "enum": [
                        "8N1",
                        "8E1",
                        "8O1"
                    ]
                },
                "timeout_ms": {
                    "type": "integer",
                    "minimum": 10
                },
                "exclusive_lock": {
                    "type": "boolean"
                }
            }
        },
        "IpcChannels": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "dds": {
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/DdsIpcChannel"
                    }
                },
                "dbus": {
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/DbusIpcChannel"
                    }
                },
                "http": {
                    "$ref": "#/definitions/HttpIpcChannel"
                },
                "serial": {
                    "$ref": "#/definitions/SerialChannel"
                }
            }
        },
        "ServiceDescriptor": {
            "type": "object",
            "required": [
                "name",
                "role",
                "slice_status",
                "binary_path",
                "systemd",
                "budgets",
                "ipc_channels",
                "dependencies"
            ],
            "additionalProperties": false,
            "allOf": [
                {
                    "if": {
                        "properties": {
                            "name": {
                                "enum": [
                                    "forward-service",
                                    "device-manager",
                                    "ui-gateway",
                                    "browser-hmi"
                                ]
                            }
                        }
                    },
                    "then": {
                        "properties": {
                            "slice_status": {
                                "const": "first_slice_active"
                            }
                        }
                    }
                },
                {
                    "if": {
                        "properties": {
                            "name": {
                                "enum": [
                                    "job-engine",
                                    "storage-service",
                                    "cloud-gateway",
                                    "camera-service",
                                    "print-guard",
                                    "system-manager"
                                ]
                            }
                        }
                    },
                    "then": {
                        "properties": {
                            "slice_status": {
                                "const": "deferred"
                            }
                        }
                    }
                }
            ],
            "properties": {
                "name": {
                    "type": "string",
                    "enum": [
                        "forward-service",
                        "device-manager",
                        "ui-gateway",
                        "browser-hmi",
                        "job-engine",
                        "storage-service",
                        "cloud-gateway",
                        "camera-service",
                        "print-guard",
                        "system-manager"
                    ]
                },
                "role": {
                    "type": "string"
                },
                "slice_status": {
                    "type": "string",
                    "enum": [
                        "first_slice_active",
                        "deferred"
                    ]
                },
                "binary_path": {
                    "type": "string"
                },
                "systemd": {
                    "$ref": "#/definitions/SystemdSpec"
                },
                "budgets": {
                    "type": "object",
                    "required": [
                        "vmware",
                        "soc"
                    ],
                    "additionalProperties": false,
                    "properties": {
                        "vmware": {
                            "$ref": "#/definitions/ResourceBudget"
                        },
                        "soc": {
                            "$ref": "#/definitions/ResourceBudget"
                        }
                    }
                },
                "ipc_channels": {
                    "$ref": "#/definitions/IpcChannels"
                },
                "dependencies": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                }
            }
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "$id": "https://aisoc.org/schemas/twin/http_sse_schema.json",
    "title": "AI-SoC Digital Twin HTTP REST and SSE Interface Specification",
    "description": "Authoritative contract schema for ui-gateway REST endpoints and SSE event streams (TWIN-02 / ICD-VMWARE-SOC-TWIN-20261029)",
    "type": "object",
    "required": [
        "endpoints",
        "sse_events"
    ],
    "properties": {
        "endpoints": {
            "type": "object",
            "required": [
                "/api/v1/temperature/snapshot",
                "/api/v1/motion/status",
                "/api/v1/hms/active"
            ],
            "properties": {
                "/api/v1/temperature/snapshot": {
                    "$ref": "#/definitions/TemperatureSnapshotResponse"
                },
                "/api/v1/motion/status": {
                    "$ref": "#/definitions/MotionStatusResponse"
                },
                "/api/v1/hms/active": {
                    "$ref": "#/definitions/HmsActiveResponse"
                }
            }
        },
        "sse_events": {
            "type": "object",
            "required": [
                "temp_update",
                "motion_update",
                "status_change",
                "alarm_event"
            ],
            "properties": {
                "temp_update": {
                    "$ref": "#/definitions/SseTempUpdateEvent"
                },
                "motion_update": {
                    "$ref": "#/definitions/SseMotionUpdateEvent"
                },
                "status_change": {
                    "$ref": "#/definitions/SseStatusChangeEvent"
                },
                "alarm_event": {
                    "$ref": "#/definitions/SseAlarmEvent"
                }
            }
        }
    },
    "definitions": {
        "SensorStatusEnum": {
            "type": "string",
            "enum": [
                "STATUS_OK",
                "STATUS_OPEN",
                "STATUS_SHORT",
                "STATUS_TIMEOUT",
                "STATUS_UNKNOWN"
            ],
            "description": "Physical sensor health condition"
        },
        "DataQualityEnum": {
            "type": "string",
            "enum": [
                "QUALITY_UNKNOWN",
                "QUALITY_FRESH",
                "QUALITY_STALE",
                "QUALITY_FAULT"
            ],
            "description": "Temporal data quality status (FRESH < 3s, STALE >= 3s, FAULT >= 10s or sensor failure)"
        },
        "TemperatureChannel": {
            "type": "object",
            "required": [
                "temperature_c",
                "temperature_millic",
                "sensor_status",
                "quality",
                "raw_adc",
                "updated_ms_ago"
            ],
            "additionalProperties": false,
            "properties": {
                "temperature_c": {
                    "type": [
                        "number",
                        "null"
                    ],
                    "minimum": -40.0,
                    "maximum": 500.0,
                    "description": "Calibrated temperature in degrees Celsius (0.1 resolution), or null if faulted/offline"
                },
                "temperature_millic": {
                    "type": "integer",
                    "description": "Normalized integer temperature in 0.001 deg C, or 2147483647 (0x7FFFFFFF) on fault, 2147483646 (0x7FFFFFFE) on offline",
                    "oneOf": [
                        {
                            "type": "integer",
                            "minimum": -40000,
                            "maximum": 500000,
                            "description": "Valid measurement range: -40.000 deg C to +500.000 deg C"
                        },
                        {
                            "type": "integer",
                            "enum": [
                                2147483647,
                                2147483646
                            ],
                            "description": "Sentinels: 2147483647 (FAULT), 2147483646 (OFFLINE)"
                        }
                    ]
                },
                "sensor_status": {
                    "$ref": "#/definitions/SensorStatusEnum"
                },
                "quality": {
                    "$ref": "#/definitions/DataQualityEnum"
                },
                "raw_adc": {
                    "type": "integer",
                    "minimum": 0,
                    "maximum": 4095,
                    "description": "12-bit ADC raw conversion readout"
                },
                "sample_tick_ms": {
                    "type": "integer",
                    "minimum": 0,
                    "description": "Monotonic timestamp of sampling tick on MCU (ms)"
                },
                "updated_ms_ago": {
                    "type": "integer",
                    "minimum": 0,
                    "description": "Elapsed milliseconds since last valid telemetry update received on host"
                }
            }
        },
        "TemperatureSnapshotResponse": {
            "type": "object",
            "required": [
                "schema_version",
                "generation_id",
                "timestamp_ms",
                "system_status",
                "bed",
                "tool"
            ],
            "additionalProperties": false,
            "properties": {
                "schema_version": {
                    "type": "integer",
                    "const": 2,
                    "description": "Fixed schema version 2 (TWIN-02)"
                },
                "generation_id": {
                    "type": "integer",
                    "minimum": 1,
                    "description": "AP service boot/restart generation ID (invalidates stale clients)"
                },
                "timestamp_ms": {
                    "type": "integer",
                    "minimum": 0,
                    "description": "Unix epoch or monotonic milliseconds when snapshot was generated"
                },
                "system_status": {
                    "type": "string",
                    "description": "Human-readable summary of subsystem operational health"
                },
                "bed": {
                    "$ref": "#/definitions/TemperatureChannel",
                    "description": "Heated bed temperature channel (MC, source_node=1)"
                },
                "tool": {
                    "$ref": "#/definitions/TemperatureChannel",
                    "description": "Toolhead / nozzle temperature channel (TH, source_node=2)"
                }
            }
        },
        "MotionStatusResponse": {
            "type": "object",
            "required": [
                "schema_version",
                "timestamp_ms",
                "x_mm",
                "y_mm",
                "z_mm",
                "e_mm",
                "feedrate_mms",
                "is_moving",
                "is_homed",
                "sequence_id"
            ],
            "additionalProperties": false,
            "properties": {
                "schema_version": {
                    "type": "integer",
                    "const": 2
                },
                "timestamp_ms": {
                    "type": "integer",
                    "minimum": 0
                },
                "x_mm": {
                    "type": "number",
                    "description": "Current X axis coordinate in millimeters"
                },
                "y_mm": {
                    "type": "number",
                    "description": "Current Y axis coordinate in millimeters"
                },
                "z_mm": {
                    "type": "number",
                    "description": "Current Z axis coordinate in millimeters"
                },
                "e_mm": {
                    "type": "number",
                    "description": "Current extruder coordinate in millimeters"
                },
                "feedrate_mms": {
                    "type": "number",
                    "minimum": 0.0,
                    "description": "Current commanded feedrate in mm/s"
                },
                "is_moving": {
                    "type": "boolean",
                    "description": "True when motion planner buffer is actively executing moves"
                },
                "is_homed": {
                    "type": "boolean",
                    "description": "True when all axes are homed"
                },
                "sequence_id": {
                    "type": "integer",
                    "minimum": 0
                }
            }
        },
        "HmsAlarm": {
            "type": "object",
            "required": [
                "alarm_id",
                "node_id",
                "error_code",
                "severity",
                "message",
                "timestamp_ms"
            ],
            "additionalProperties": false,
            "properties": {
                "alarm_id": {
                    "type": "integer",
                    "minimum": 1
                },
                "node_id": {
                    "type": "integer",
                    "enum": [
                        1,
                        2,
                        3
                    ],
                    "description": "1 = MC, 2 = TH, 3 = AP"
                },
                "error_code": {
                    "type": "integer"
                },
                "severity": {
                    "type": "string",
                    "enum": [
                        "INFO",
                        "WARNING",
                        "ERROR",
                        "CRITICAL"
                    ]
                },
                "message": {
                    "type": "string"
                },
                "timestamp_ms": {
                    "type": "integer",
                    "minimum": 0
                }
            }
        },
        "HmsActiveResponse": {
            "type": "object",
            "required": [
                "schema_version",
                "timestamp_ms",
                "total_active",
                "active_alarms"
            ],
            "additionalProperties": false,
            "properties": {
                "schema_version": {
                    "type": "integer",
                    "const": 2
                },
                "timestamp_ms": {
                    "type": "integer",
                    "minimum": 0
                },
                "total_active": {
                    "type": "integer",
                    "minimum": 0
                },
                "active_alarms": {
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/HmsAlarm"
                    }
                }
            }
        },
        "SseTempUpdateEvent": {
            "type": "object",
            "required": [
                "timestamp_ms",
                "bed_c",
                "tool_c",
                "bed_q",
                "tool_q",
                "bed_status",
                "tool_status"
            ],
            "additionalProperties": false,
            "properties": {
                "timestamp_ms": {
                    "type": "integer",
                    "minimum": 0
                },
                "bed_c": {
                    "type": [
                        "number",
                        "null"
                    ],
                    "description": "Bed temperature in deg C, or null on fault/offline"
                },
                "tool_c": {
                    "type": [
                        "number",
                        "null"
                    ],
                    "description": "Toolhead temperature in deg C, or null on fault/offline"
                },
                "bed_q": {
                    "type": "string",
                    "enum": [
                        "FRESH",
                        "STALE",
                        "FAULT",
                        "UNKNOWN"
                    ]
                },
                "tool_q": {
                    "type": "string",
                    "enum": [
                        "FRESH",
                        "STALE",
                        "FAULT",
                        "UNKNOWN"
                    ]
                },
                "bed_status": {
                    "$ref": "#/definitions/SensorStatusEnum"
                },
                "tool_status": {
                    "$ref": "#/definitions/SensorStatusEnum"
                }
            }
        },
        "SseMotionUpdateEvent": {
            "type": "object",
            "required": [
                "timestamp_ms",
                "x_mm",
                "y_mm",
                "z_mm",
                "e_mm",
                "feedrate_mms",
                "is_moving",
                "is_homed"
            ],
            "additionalProperties": false,
            "properties": {
                "timestamp_ms": {
                    "type": "integer",
                    "minimum": 0
                },
                "x_mm": {
                    "type": "number"
                },
                "y_mm": {
                    "type": "number"
                },
                "z_mm": {
                    "type": "number"
                },
                "e_mm": {
                    "type": "number"
                },
                "feedrate_mms": {
                    "type": "number"
                },
                "is_moving": {
                    "type": "boolean"
                },
                "is_homed": {
                    "type": "boolean"
                }
            }
        },
        "SseStatusChangeEvent": {
            "type": "object",
            "required": [
                "timestamp_ms",
                "system_state",
                "mc_link",
                "th_link",
                "reason"
            ],
            "additionalProperties": false,
            "properties": {
                "timestamp_ms": {
                    "type": "integer",
                    "minimum": 0
                },
                "system_state": {
                    "type": "string",
                    "enum": [
                        "INITIALIZING",
                        "OPERATIONAL",
                        "DEGRADED",
                        "FAULT",
                        "EMERGENCY_STOP"
                    ]
                },
                "mc_link": {
                    "type": "boolean"
                },
                "th_link": {
                    "type": "boolean"
                },
                "reason": {
                    "type": "string"
                }
            }
        },
        "SseAlarmEvent": {
            "type": "object",
            "required": [
                "timestamp_ms",
                "action",
                "alarm_id",
                "node_id",
                "severity",
                "message"
            ],
            "additionalProperties": false,
            "properties": {
                "timestamp_ms": {
                    "type": "integer",
                    "minimum": 0
                },
                "action": {
                    "type": "string",
                    "enum": [
                        "RAISED",
                        "CLEARED"
                    ]
                },
                "alarm_id": {
                    "type": "integer"
                },
                "node_id": {
                    "type": "integer"
                },
                "severity": {
                    "type": "string",
                    "enum": [
                        "INFO",
                        "WARNING",
                        "ERROR",
                        "CRITICAL"
                    ]
                },
                "message": {
                    "type": "string"
                }
            }
        }
    }
}

